import{_ as a,o as t,c as s,a2 as i}from"./chunks/framework.CodEvmtK.js";const u=JSON.parse('{"title":"Working with AI assistants","description":"","frontmatter":{},"headers":[],"relativePath":"ai-assistants.md","filePath":"ai-assistants.md","lastUpdated":1790947166000}'),o={name:"ai-assistants.md"};function n(l,e,r,d,p,c){return t(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="working-with-ai-assistants" tabindex="-1">Working with AI assistants <a class="header-anchor" href="#working-with-ai-assistants" aria-label="Permalink to &quot;Working with AI assistants&quot;">​</a></h1><p>Open Ink is designed so that an assistant (Claude Code, Cursor, Copilot, ChatGPT…) can turn a description into a prototype <strong>without writing HTML</strong>:</p><blockquote><p>&quot;Wireframe a marketplace for used bikes: search with filters, listing page with a contact form, seller dashboard.&quot;</p></blockquote><p>The assistant writes <code>spec.yaml</code>, the tool checks it, and you get a consistent hand-drawn result. Because the spec is small and validated, it is cheap to iterate: &quot;add a second tab to the listing page&quot; is a five-line diff.</p><h2 id="install-the-open-ink-skill" tabindex="-1">Install the Open Ink skill <a class="header-anchor" href="#install-the-open-ink-skill" aria-label="Permalink to &quot;Install the Open Ink skill&quot;">​</a></h2><p>Open Ink comes with a <code>wireframe</code> skill that teaches your agent the whole loop. Once it is installed, the agent uses it whenever you ask for a wireframe, mockup or clickable prototype, in any folder, so you do not need to mention Open Ink or run <code>init</code> first.</p><p>The skill follows the same steps as the <code>AGENTS.md</code> below: it reads the block reference, edits only <code>spec.yaml</code>, validates until the spec is clean, checks a PNG of every screen and tells you where the result is. In a folder without a spec, it creates the project in a new subfolder so it does not overwrite your files.</p><h3 id="claude-code" tabindex="-1">Claude Code <a class="header-anchor" href="#claude-code" aria-label="Permalink to &quot;Claude Code&quot;">​</a></h3><p>Install the plugin once:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">claude</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> plugin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> marketplace</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mediuswareltd/openink</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">claude</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> plugin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> openink@openink</span></span></code></pre></div><p>Inside a session the same is <code>/plugin marketplace add mediuswareltd/openink</code> and <code>/plugin install openink@openink</code>. You can also call the skill directly with <code>/openink:wireframe</code>.</p><p>For updates, turn on auto-update for the <strong>openink</strong> marketplace in <code>/plugin</code> → <strong>Marketplaces</strong>, or run <code>/plugin marketplace update openink</code>.</p><h3 id="cursor-codex-gemini-cli-github-copilot-and-other-agents" tabindex="-1">Cursor, Codex, Gemini CLI, GitHub Copilot and other agents <a class="header-anchor" href="#cursor-codex-gemini-cli-github-copilot-and-other-agents" aria-label="Permalink to &quot;Cursor, Codex, Gemini CLI, GitHub Copilot and other agents&quot;">​</a></h3><p>Add the skill with the <a href="https://skills.sh" target="_blank" rel="noreferrer">skills</a> CLI:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> skills</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mediuswareltd/openink</span></span></code></pre></div><p>It asks which of your agents to install it for, and whether to install it for this project or for your user. To skip the questions, name the agents and add <code>-y</code>, for example <code>npx skills add mediuswareltd/openink -a cursor -a codex -y</code>, and add <code>-g</code> to install it for every project. Run <code>npx skills update</code> to get the latest version.</p><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><p><code>openink init</code> puts an <code>AGENTS.md</code> in your project. Most assistants read it automatically; it tells them to:</p><ol><li>Run <code>npx openink blocks</code> to learn the available blocks.</li><li>Edit <code>spec.yaml</code> only.</li><li>Run <code>npx openink validate</code> and fix what it reports.</li><li>Run <code>npx openink png</code> and look at <code>dist/png/*.png</code> to check the layout.</li></ol><p>If your assistant uses a different filename (<code>CLAUDE.md</code>, <code>.cursorrules</code>, …), copy or rename <code>AGENTS.md</code>.</p><h2 id="why-validation-matters-here" tabindex="-1">Why validation matters here <a class="header-anchor" href="#why-validation-matters-here" aria-label="Permalink to &quot;Why validation matters here&quot;">​</a></h2><p>Assistants make small mistakes: a misspelt prop, a link to a screen they renamed, a translation missing in one language. <code>validate</code> reports each with its exact location in the spec and a &quot;did you mean&quot; hint, so the fix-and-retry loop is short and mechanical:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>✗ 2 problems in the spec</span></span>
<span class="line"><span>  error screens[1].blocks[3].type: Unknown block type &quot;buton&quot;. Did you mean &quot;button&quot;?</span></span>
<span class="line"><span>  error screens[0].blocks[0].go: Links to unknown screen &quot;checkout&quot;. Did you mean &quot;check-out&quot;?</span></span></code></pre></div><h2 id="tips-for-good-prompts" tabindex="-1">Tips for good prompts <a class="header-anchor" href="#tips-for-good-prompts" aria-label="Permalink to &quot;Tips for good prompts&quot;">​</a></h2><ul><li>Name the <strong>users</strong> and their <strong>goals</strong>, not the widgets: &quot;a tenant who wants to find a flat in Zurich&quot;.</li><li>Say which <strong>states</strong> matter (empty, error, paid, unpaid); each becomes a screen or a <code>note:</code>.</li><li>Ask for <code>note:</code> on anything a sketch can&#39;t show (&quot;results update live, there is no search button&quot;).</li><li>Mention languages up front if you need them.</li></ul>`,25)])])}const k=a(o,[["render",n]]);export{u as __pageData,k as default};
